package vn.venusgiti.vticket;

import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.*;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.nio.charset.StandardCharsets;
import vn.venusgiti.vticket.Domain.*;
import vn.venusgiti.vticket.Requests.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:paymenttest;MODE=MSSQLServer;DB_CLOSE_DELAY=-1","app.seed-data=false","app.vietqr.enabled=true","app.vietqr.client.username=unit-test","app.vietqr.bank.account=000000000000","app.vietqr.bank.account-name=VENUSGITI TEST","app.vietqr.callback.username=callback-test"})
@ActiveProfiles("demo") @AutoConfigureMockMvc @Import(VietQrPaymentIntegrationTest.FakeConfig.class)
class VietQrPaymentIntegrationTest {
 static final String CALLBACK_PASSWORD=UUID.randomUUID().toString(),SECRET=UUID.randomUUID().toString()+UUID.randomUUID();
 @DynamicPropertySource static void secrets(DynamicPropertyRegistry r){r.add("app.vietqr.callback.password",()->CALLBACK_PASSWORD);r.add("app.vietqr.callback.jwt-secret",()->SECRET);r.add("app.vietqr.client.password",()->UUID.randomUUID().toString());}
 @TestConfiguration static class FakeConfig { @Bean @Primary FakeGateway fake(){return new FakeGateway();} }
 static class FakeGateway implements VietQrGateway {
  final AtomicInteger calls=new AtomicInteger();final AtomicBoolean fail=new AtomicBoolean();
  public Generated generate(String id,BigDecimal amount,String content){calls.incrementAndGet();if(fail.getAndSet(false))throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Test provider unavailable");return new Generated("MB","000000000000","VENUSGITI TEST",amount,"PREFIX "+content,"TEST-PAYLOAD-"+id,"reference-"+id,"https://dev.vietqr.org/test",null,id);}
 }
 @Autowired Products products;@Autowired InventoryService inventory;@Autowired BookingService bookings;@Autowired Bookings orders;@Autowired VietQrPaymentService payments;@Autowired PaymentIntents intents;@Autowired PaymentReceipts receipts;@Autowired MockMvc mvc;@Autowired VietQrCallbackTokens tokens;@Autowired Tickets tickets;@Autowired FakeGateway gateway;@Autowired Vouchers vouchers;
 Product product;
 @BeforeEach void setup(){gateway.fail.set(false);product=new Product();product.code="PAY-"+UUID.randomUUID();product.name="Vé thanh toán";product.kind=Kind.TICKET;product.price=BigDecimal.valueOf(250000);product=products.saveAndFlush(product);var date=LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh"));inventory.createBatch(new BatchInput("PAY-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(Locale.ROOT),product.id,20,date,date.plusYears(1)),"test");}
 Booking order(Channel channel){return bookings.create(new OrderInput("Khách thử","0900000000","",LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")),null,List.of(new LineInput(product.id,2))),channel,channel==Channel.COUNTER?"staff":"guest");}
 VietQrCallbackController.SyncRequest event(VietQrPaymentService.View v){return new VietQrCallbackController.SyncRequest(v.bankAccount(),v.amount(),"C",v.content(),UUID.randomUUID().toString(),Instant.now().toEpochMilli(),UUID.randomUUID().toString(),v.orderId(),null,null,null,null,null);}
 VietQrCallbackController.SyncRequest changed(VietQrCallbackController.SyncRequest e,String account,BigDecimal amount,String type,String content,String orderId){return new VietQrCallbackController.SyncRequest(account,amount,type,content,e.transactionid(),e.transactiontime(),e.referencenumber(),orderId,null,null,null,null,null);}
 @Test void createQrDoesNotMarkPaidAndReusesProviderOrder(){var b=order(Channel.ONLINE);int start=gateway.calls.get();var p=payments.initiate(b.accessToken);var again=payments.initiate(b.accessToken);assertEquals(13,p.orderId().length());assertEquals(p.orderId(),again.orderId());assertEquals(start+1,gateway.calls.get());assertEquals(Status.PENDING,orders.findById(b.id).orElseThrow().status);assertTrue(tickets.findByBookingId(b.id).isEmpty());}
 @Test void callbackPaysOnlineAndExposesPdf()throws Exception{var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);mvc.perform(get("/api/public/orders/"+b.accessToken+"/tickets.pdf")).andExpect(status().isConflict());mvc.perform(post("/vietqr/bank/api/transaction-sync").header("Authorization","Bearer "+tokens.create()).contentType("application/json").content(json(e))).andExpect(status().isOk()).andExpect(jsonPath("$.error").value(false));assertEquals(Status.PAID,orders.findById(b.id).orElseThrow().status);assertEquals("VIETQR",orders.findById(b.id).orElseThrow().paymentMethod);assertEquals(2,tickets.findByBookingId(b.id).size());mvc.perform(get("/api/public/orders/"+b.accessToken+"/tickets.pdf")).andExpect(status().isOk()).andExpect(content().contentType("application/pdf"));}
 @Test void callbackAlsoPaysCounter(){var b=order(Channel.COUNTER);var p=payments.initiate(b.accessToken);assertEquals(ReceiptState.APPLIED,payments.callback(event(p)).state);assertEquals(2,tickets.findByBookingId(b.id).size());}
 @Test void repeatedCallbackDoesNotIssueAgain(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);var first=payments.callback(e);var next=payments.callback(e);assertEquals(first.id,next.id);assertEquals(2,tickets.findByBookingId(b.id).size());}
 @Test void sameBankReferenceWithNewTransactionIdIsDeduplicated(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);var first=payments.callback(e);var duplicate=new VietQrCallbackController.SyncRequest(e.bankaccount(),e.amount(),e.transType(),e.content(),UUID.randomUUID().toString(),e.transactiontime(),e.referencenumber(),e.orderId(),null,null,null,null,null);assertEquals(first.id,payments.callback(duplicate).id);assertEquals(2,tickets.findByBookingId(b.id).size());}
 @Test void conflictingDuplicateCannotPayAnotherOrder(){var a=order(Channel.ONLINE);var b=order(Channel.ONLINE);var pa=payments.initiate(a.accessToken);var pb=payments.initiate(b.accessToken);var e=event(pa);payments.callback(e);assertThrows(ResponseStatusException.class,()->payments.callback(changed(e,e.bankaccount(),e.amount(),e.transType(),pb.content(),pb.orderId())));assertEquals(Status.PENDING,orders.findById(b.id).orElseThrow().status);}
 @Test void wrongAmountNeedsReviewAndNeverIssues(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);var r=payments.callback(changed(e,e.bankaccount(),e.amount().subtract(BigDecimal.ONE),e.transType(),e.content(),e.orderId()));assertEquals("WRONG_AMOUNT",r.reason);assertEquals(ReceiptState.REVIEW,r.state);assertEquals(Status.PENDING,orders.findById(b.id).orElseThrow().status);assertTrue(tickets.findByBookingId(b.id).isEmpty());assertEquals(ReceiptState.APPLIED,payments.callback(event(p)).state);}
 @Test void wrongAccountNeedsReview(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);assertEquals("WRONG_ACCOUNT",payments.callback(changed(e,"111111111111",e.amount(),e.transType(),e.content(),e.orderId())).reason);}
 @Test void debitNeedsReview(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);assertEquals("NOT_CREDIT",payments.callback(changed(e,e.bankaccount(),e.amount(),"D",e.content(),e.orderId())).reason);}
 @Test void wrongContentNeedsReview(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);assertEquals("CONTENT_MISMATCH",payments.callback(changed(e,e.bankaccount(),e.amount(),e.transType(),"Other transaction",e.orderId())).reason);}
 @Test void unknownOrderIsStoredForReview(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);assertEquals("UNKNOWN_ORDER",payments.callback(changed(e,e.bankaccount(),e.amount(),e.transType(),e.content(),"UNKNOWN")).reason);}
 @Test void latePaymentDoesNotReuseReleasedStock(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var modified=orders.findById(b.id).orElseThrow();modified.expiresAt=Instant.now().minusSeconds(1);orders.saveAndFlush(modified);bookings.cancel(b.id,"system",true);var r=payments.callback(event(p));assertEquals(ReceiptState.REVIEW,r.state);assertTrue(tickets.findByBookingId(b.id).isEmpty());}
 @Test void extraPaymentAfterSuccessNeedsReview(){var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);payments.callback(event(p));assertEquals("ALREADY_PAID",payments.callback(event(p)).reason);assertEquals(2,tickets.findByBookingId(b.id).size());}
 @Test void expiredVoucherReviewCommitsReceipt(){var v=new Voucher();v.code="VG-"+UUID.randomUUID().toString().toUpperCase(Locale.ROOT);v.customerName="Khách";v.phone="0900000000";v.percentage=10;v.validFrom=Instant.now().minusSeconds(60);v.validUntil=Instant.now().plusSeconds(600);v=vouchers.saveAndFlush(v);var b=bookings.create(new OrderInput("Khách","0900000000","",LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")),v.code,List.of(new LineInput(product.id,1))),Channel.ONLINE,"guest");var p=payments.initiate(b.accessToken);v.validUntil=Instant.now().minusSeconds(1);vouchers.saveAndFlush(v);var r=payments.callback(event(p));assertEquals("VOUCHER_INVALID",r.reason);assertTrue(receipts.findById(r.id).isPresent());assertTrue(tickets.findByBookingId(b.id).isEmpty());}
 @Test void failedGenerationRetainsOrderIdForRetry(){var b=order(Channel.ONLINE);gateway.fail.set(true);assertThrows(ResponseStatusException.class,()->payments.initiate(b.accessToken));var failed=intents.findByBookingId(b.id).orElseThrow();assertEquals(IntentState.FAILED,failed.state);assertEquals(failed.id,payments.initiate(b.accessToken).orderId());}
 @Test void callbackCredentialsAreSeparateFromStaff()throws Exception{mvc.perform(post("/vietqr/api/token_generate").header("Authorization","Basic "+Base64.getEncoder().encodeToString(("callback-test:"+CALLBACK_PASSWORD).getBytes(StandardCharsets.UTF_8)))).andExpect(status().isOk()).andExpect(jsonPath("$.token_type").value("Bearer")).andExpect(jsonPath("$.expires_in").value(300));mvc.perform(post("/vietqr/api/token_generate").with(httpBasic("staff","demo-staff-change-me"))).andExpect(status().isUnauthorized());}
 @Test void callbackWithoutBearerCannotPay()throws Exception{var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);mvc.perform(post("/vietqr/bank/api/transaction-sync").contentType("application/json").content(json(event(p)))).andExpect(status().isUnauthorized());mvc.perform(post("/api-vietqr-callback/api-transaction-sync").with(httpBasic("admin","demo-admin-change-me")).contentType("application/json").content(json(event(p)))).andExpect(status().isUnauthorized());}
 @Test void callbackBearerCannotAccessAdmin()throws Exception{mvc.perform(get("/api/admin/products").header("Authorization","Bearer "+tokens.create())).andExpect(status().isUnauthorized());}
 @Test void aliasesAcceptCallbackWithSameBearer()throws Exception{var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);mvc.perform(post("/api-vietqr-callback/api-transaction-sync").header("Authorization","Bearer "+tokens.create()).contentType("application/json").content(json(event(p)))).andExpect(status().isOk()).andExpect(jsonPath("$.error").value(false));}
 @Test void onlineCashIsForbiddenAndCounterCashWorks()throws Exception{var online=order(Channel.ONLINE);mvc.perform(post("/api/staff/orders/"+online.id+"/cash").with(csrf()).with(httpBasic("staff","demo-staff-change-me"))).andExpect(status().isConflict());var counter=order(Channel.COUNTER);mvc.perform(post("/api/staff/orders/"+counter.id+"/cash").with(csrf()).with(httpBasic("staff","demo-staff-change-me"))).andExpect(status().isOk()).andExpect(jsonPath("$.paymentMethod").value("CASH"));}
 @Test void cannotConfirmCashAfterQrSelection(){var b=order(Channel.COUNTER);payments.initiate(b.accessToken);assertThrows(ResponseStatusException.class,()->bookings.cash(b.id,"staff"));}
 @Test void qrImageUsesExactProviderPayload()throws Exception{var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);byte[] bytes=mvc.perform(get("/api/public/orders/"+b.accessToken+"/vietqr/image")).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();var image=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes));var bitmap=new com.google.zxing.BinaryBitmap(new com.google.zxing.common.HybridBinarizer(new com.google.zxing.client.j2se.BufferedImageLuminanceSource(image)));assertEquals("TEST-PAYLOAD-"+p.orderId(),new com.google.zxing.MultiFormatReader().decode(bitmap).getText());}
 @Test void csrfStillProtectsCustomerAndStaffActions()throws Exception{var b=order(Channel.ONLINE);mvc.perform(post("/api/public/orders/"+b.accessToken+"/vietqr")).andExpect(status().isForbidden());}
 @Test void noPublicFakePaymentEndpoint()throws Exception{var b=order(Channel.ONLINE);mvc.perform(post("/api/public/orders/"+b.accessToken+"/demo-pay").with(csrf())).andExpect(status().isNotFound());}
 @Test void zeroTotalNeedsNoBankTransfer(){product.price=BigDecimal.ZERO;products.saveAndFlush(product);var b=order(Channel.ONLINE);assertThrows(ResponseStatusException.class,()->payments.initiate(b.accessToken));var paid=bookings.confirmZero(b.accessToken);assertEquals(Status.PAID,paid.status);assertNull(paid.paymentMethod);assertEquals(2,tickets.findByBookingId(b.id).size());}
 @Test void concurrentDuplicateCallbacksIssueOnce()throws Exception{var b=order(Channel.ONLINE);var p=payments.initiate(b.accessToken);var e=event(p);var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{Callable<String> f=()->{start.await();return payments.callback(e).id;};var a=pool.submit(f);var c=pool.submit(f);start.countDown();assertEquals(a.get(20,TimeUnit.SECONDS),c.get(20,TimeUnit.SECONDS));assertEquals(2,tickets.findByBookingId(b.id).size());}finally{pool.shutdownNow();}}
 String json(Object value){return tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(value);}
}
